// 風俗系シチュプリセット注入関数

window._injectFuzokuPreset = function(charId, pgIdx, pnIdx) {

  var presetKey = null;

  if (/^char_soap_/.test(charId))        presetKey = "soap";

  else if (/^char_pinsaro_/.test(charId)) presetKey = "pinsaro";

  else if (/^char_(pov_)?deliheru_/.test(charId)) presetKey = "deliheru";

  else if (/^char_(kyaba_|pov_kyaba_)/.test(charId)) presetKey = "kyaba";

  else if (/^char_sekkya_/.test(charId)) presetKey = "sekkya";

  else if (/^char_rifure_/.test(charId))  presetKey = "rifure";

  else if (/^char_hakohealth_/.test(charId)) presetKey = "hakohealth";

  else if (/^char_cosplay_/.test(charId)) presetKey = "cosplay";

  if (!presetKey) return;

  var list = window._FUZOKU_PRESETS[presetKey];

  if (!list) return;

  // ドロップダウンを動的生成・表示

  var existing = document.getElementById("_fuzoku_situ_bar");

  if (existing) existing.remove();

  var emPromptEl = document.getElementById("_em_prompt");

  if (!emPromptEl) return;

  var bar = document.createElement("div");

  bar.id = "_fuzoku_situ_bar";

  bar.style.cssText = "margin-bottom:6px;background:#0f172a;border:1px solid #1e40af;border-radius:6px;padding:6px 8px";

  var label = document.createElement("div");

  label.style.cssText = "font-size:11px;color:#93c5fd;margin-bottom:4px;font-weight:bold";

  var emoji = {soap:"🛁",pinsaro:"💈",deliheru:"🚗",kyaba:"🥂",sekkya:"💋",rifure:"🛁",hakohealth:"📦",cosplay:"👘"}[presetKey] || "🎬";

  label.textContent = emoji + " シチュエーション選択（" + list.length + "シーン）";

  bar.appendChild(label);

  var sel = document.createElement("select");

  sel.style.cssText = "width:100%;background:#1e293b;color:#e2e8f0;border:1px solid #334155;border-radius:4px;padding:4px 6px;font-size:12px;cursor:pointer";

  var blank = document.createElement("option");

  blank.value = "";

  blank.textContent = "-- シーンを選んでクリックで挿入 --";

  sel.appendChild(blank);

  list.forEach(function(item) {

    var opt = document.createElement("option");

    opt.value = item.v;

    opt.textContent = item.l;

    sel.appendChild(opt);

  });

  sel.onchange = function() {

    if (!this.value) return;

    var ta = document.getElementById("_em_prompt");

    if (!ta) return;

    var cur = ta.value.trim();

    ta.value = cur ? cur + "," + this.value : this.value;

    ta.dispatchEvent(new Event("input"));

    // 選択リセット

    this.selectedIndex = 0;

  };

  bar.appendChild(sel);

  emPromptEl.parentNode.insertBefore(bar, emPromptEl);

};

// ===== END 風俗系プリセット =====

